 *
 * Kept as one value, rather than a handful of loose accumulators, so that a
 * step's effect on later steps is a single readable transition: `officeAfter`
 * below is the only place the ledger advances.
 */
interface Office {
  readonly customer: Customer;
  readonly quotesSoFar: number;
}

const openOffice = (customer: Customer): Office => ({ customer, quotesSoFar: 0 });

const standingAt = (office: Office): CustomerStanding => ({
  customer: office.customer,
  quotesSoFar: office.quotesSoFar,
});

/** The result of a step, and the ledger as the *next* step will find it. */
interface StepOutcome {
  readonly result: QuoteResult;
  readonly office: Office;
}

